import { z } from "zod";

export const AGENT_LANGUAGES = ["en", "fr", "pidgin"] as const;
export type AgentLanguage = (typeof AGENT_LANGUAGES)[number];

export const AGENT_URGENCY = ["low", "normal", "high", "safety"] as const;
export type AgentUrgency = (typeof AGENT_URGENCY)[number];

/**
 * Fixed, human-written safety phrases. Never generated by the model: a model
 * must never tell a customer a price, an arrival time, or a diagnosis.
 */
export const SAFETY_TERMS = ["sparks", "sparking", "burning smell", "gas", "smoke", "étincelles", "odeur de brûlé", "gaz", "fumée"] as const;

