const confidence = <T extends z.ZodTypeAny>(field: T) => z.number().min(0).max(1).describe(`Confidence in ${field.description ?? "this field"}`);

export const jobDraftSchema = z.object({
  customerName: z.string().trim().max(120).nullable(),
  phone: z.string().trim().max(40).nullable(),
  town: z.string().trim().max(120).nullable(),
  neighborhood: z.string().trim().max(120).nullable(),
  landmarkDirections: z.string().trim().max(500).nullable(),
  applianceType: z.string().trim().max(120).nullable(),
  brand: z.string().trim().max(120).nullable(),
  symptom: z.string().trim().max(1000).nullable(),
  urgency: z.enum(AGENT_URGENCY).nullable(),
  preferredTime: z.string().trim().max(120).nullable(),
  language: z.enum(AGENT_LANGUAGES),
  photoReferences: z.array(z.string().trim().min(1)).max(10),
  confidence: z.object({
    customerName: confidence(z.string()),
    phone: confidence(z.string()),
    town: confidence(z.string()),
    neighborhood: confidence(z.string()),
    landmarkDirections: confidence(z.string()),
    applianceType: confidence(z.string()),
    brand: confidence(z.string()),
    symptom: confidence(z.string()),
    urgency: confidence(z.string()),
    preferredTime: confidence(z.string()),
  }),
  missingFields: z.array(z.string().trim().min(1)).max(10),
  safetyFlags: z.array(z.string().trim().min(1)).max(10),
});

export type JobDraft = z.infer<typeof jobDraftSchema>;

export const jobDraftQuestionSchema = z.object({
  language: z.enum(AGENT_LANGUAGES),
  questions: z.array(z.string().trim().min(1).max(300)).max(3),
  fields: z.array(z.string().trim().min(1)).max(3),
});

export type JobDraftQuestion = z.infer<typeof jobDraftQuestionSchema>;

/** Fields the dispatcher must see before a draft can be turned into a job. */
export const JOB_DRAFT_KEY_FIELDS = ["customerName", "phone", "town", "applianceType", "symptom"] as const;

export const AGENT_RUN_TASKS = ["agent.extract", "agent.stt", "agent.followup"] as const;
export type AgentRunTask = (typeof AGENT_RUN_TASKS)[number];
